#!/usr/bin/env python3
import json,math
from pathlib import Path
R=Path(__file__).resolve().parent;d=json.loads((R/'design.json').read_text());parts={p['ref']:p for p in d['parts']}
body={'U1':[-1.27,-1.4,24.13,61.34],'U2':[-1.27,-1.575,24.13,46.685],'U3':[-1.27,-2.921,16.51,18.034],'U4':[-1.34,-6.4,21.66,18.6]}
def bbox(p,b):
 t=math.radians(p['rotation']);c=[(p['xy'][0]+x*math.cos(t)+y*math.sin(t),p['xy'][1]-x*math.sin(t)+y*math.cos(t)) for x,y in [b[:2],b[2:]]];return [round(min(x for x,y in c),4),round(min(y for x,y in c),4),round(max(x for x,y in c),4),round(max(y for x,y in c),4)]
modules={r:dict(anchor_mm=parts[r]['xy'],rotation_deg=parts[r]['rotation'],pcb_body_bounds_mm=bbox(parts[r],b)) for r,b in body.items()}
report=dict(status='separate_geometry_study_not_active_design',board_mm=[100,100],copper_layers=2,area_mm2=10000,active_area_mm2=9000,area_increase_percent=100/9,modules=modules,part_count=17,pad_count=145,connected_pad_count=103,connector_removal_required=False,new_electronic_parts=0,assembly_side='all top',usb_service_envelopes_mm=d['mechanics']['usb_service_envelopes_mm'],header_housing_envelopes_mm=d['mechanics']['header_mating_envelopes_mm'],antenna_bounds_mm={'H2':[43.97,53.575,57.17,58.975],'XIAO_MG24':[-.0339,67.6996,1.9661,72.8996]},clearances_mm={'H2_antenna_to_WIZ_PCB':15.325,'H2_antenna_to_S3_PCB_lateral':15.56,'H2_antenna_to_XIAO_PCB_lateral':23.049,'XIAO_USB_envelope_to_H2_antenna':.645,'XIAO_USB_envelope_to_WIZ_PCB':.680,'XIAO_USB_envelope_to_WIZ_courtyard':.180},rf_copper_keepouts_mm=d['mechanics']['rf_copper_keepouts_mm'],limitations=['H2 antenna is internal; geometric spacing and copper keepout require RF bench confirmation','XIAO USB envelope is narrow; measure actual shell and vertical cable exit','Temporary XIAO USB cable enters H2 RF clearance; no permanent pigtail there','See service-review.md for corrected XIAO VIN/VBUS/SAMD11 programming power','Enclosure, nylon supports, insertion force, module pin fit and thermal operation untested'],rejected_placement={'XIAO_anchor_mm':[18,52],'reason':'30x14mm USB envelope overlaps H2 PCB and antenna; lowering to y59 resolves the declared envelope collision'})
(R/'geometry-study.json').write_text(json.dumps(report,indent=2)+'\n')
